# Which mark stands for which source / credential. A credential shows the mark
# of what it unlocks (every X backend key shows the X mark), because that is
# the question a user is actually answering when they look at the row.
SOURCE_ICON: dict[str, str] = {
    "arxiv": "arxiv",
    "bluesky": "bluesky",
    "digg": "digg",
    "github": "github",
    "hackernews": "hackernews",
    "instagram": "instagram",
    "meta_ads": "meta",
    "perplexity": "perplexity",
    "pinterest": "pinterest",
    "reddit": "reddit",
    "telegram": "telegram",
    "threads": "threads",
    "tiktok": "tiktok",
    "trustpilot": "trustpilot",
    "x": "x",
    "xiaohongshu": "xiaohongshu",
    "youtube": "youtube",
}

KEY_ICON: dict[str, str] = {
    "AUTH_TOKEN": "x",
    "CT0": "x",
    "GETXAPI_KEY": "x",
    "XQUIK_API_KEY": "x",
    "XAI_API_KEY": "x",
    "X_BEARER_TOKEN": "x",
    "BSKY_HANDLE": "bluesky",
    "BSKY_APP_PASSWORD": "bluesky",
    "BRAVE_API_KEY": "brave",
    "GITHUB_TOKEN": "github",
    "PERPLEXITY_API_KEY": "perplexity",
    "OPENROUTER_API_KEY": "openrouter",
    "GOOGLE_API_KEY": "gemini",
    "GEMINI_API_KEY": "gemini",
    "GOOGLE_GENAI_API_KEY": "gemini",
    "XIAOHONGSHU_API_BASE": "xiaohongshu",
}

# Monogram fallbacks are keyed by a token derived from the source or
# credential name, so a new X backend key lands on "GX"-style initials rather
# than a blank chip.
KEY_MONOGRAM: dict[str, str] = {
    "SCRAPECREATORS_API_KEY": "scrapecreators",
    "OPENAI_API_KEY": "openai",
    "EXA_API_KEY": "exa",
    "SERPER_API_KEY": "serper",
    "PARALLEL_API_KEY": "parallel",
    "APIFY_API_TOKEN": "apify",
    "BRIGHTDATA_API_KEY": "brightdata",
    "TRUTHSOCIAL_TOKEN": "truthsocial",
}


def _monogram_colors(token: str) -> tuple[str, str]:
    """Stable, pleasant accent for a monogram chip.

    Derived from the token so a given brand always gets the same colour,
    spread across the hue wheel so neighbouring chips stay distinguishable.
    """
    hue = sum(ord(c) * (i + 7) for i, c in enumerate(token)) % 360
    return f"hsl({hue} 48% 40%)", f"hsl({hue} 60% 70%)"


def _monogram(token: str, fallback_label: str) -> dict[str, str]:
    text = MONOGRAMS.get(token)
    if text is None:
        cleaned = [p for p in fallback_label.replace("_", " ").split() if p]
        text = (cleaned[0][:2] if cleaned else "?").upper()
    light, dark = _monogram_colors(token)
    return {"kind": "mono", "text": text, "light": light, "dark": dark}


def _mark(entry: dict[str, str]) -> dict[str, str]:
    return {
        "kind": "path",
        "d": entry["d"],
        "light": entry["light"],
        "dark": entry["dark"],
    }


def icon_for_source(source_id: str, label: str = "") -> dict[str, str]:
    slug = SOURCE_ICON.get(source_id)
    if slug and slug in BRAND_ICONS:
        return _mark(BRAND_ICONS[slug])
    if source_id in GENERIC_ICONS:
        return _mark(GENERIC_ICONS[source_id])
    return _monogram(source_id, label or source_id)


def icon_for_key(key_name: str, label: str = "") -> dict[str, str]:
    slug = KEY_ICON.get(key_name)
    if slug and slug in BRAND_ICONS:
        return _mark(BRAND_ICONS[slug])
    token = KEY_MONOGRAM.get(key_name, key_name.lower())
    return _monogram(token, label or key_name)
